#include <cstdint>
#include <cstdio>

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 1000) return 1;
    std::int64_t total = 0;
    for (int i = 0; i < n; i++) {
        long long value = 0;
        if (std::scanf("%lld", &value) != 1) return 1;
        if (value < -1000000000000LL || value > 1000000000000LL) return 1;
        total += static_cast<std::int64_t>(value);
    }
    std::printf("%lld\n", static_cast<long long>(total));
    return 0;
}
